// Elige UN pull request abierto al que no se le haya dado ya la primera pasada.
//
// La clave es numero+sha de la cabeza, no solo el numero: si empujas mas commits al
// mismo PR, vuelve a entrar. Asi la pasada sigue al codigo, no a la conversacion.
const estado = $getWorkflowStaticData('global');
estado.revisados = estado.revisados || [];

const abiertos = ($input.all() || []).map(i => i.json)
  // Los borradores no se tocan: un borrador es trabajo a medias y comentarlo es ruido.
  .filter(p => !p.draft)
  .filter(p => !estado.revisados.includes(p.number + '@' + p.head?.sha));

const pr = abiertos[0];
if (!pr) return [];

return [{ json: {
  numero: pr.number,
  titulo: pr.title,
  cuerpo: (pr.body || '').slice(0, 2000),
  sha: pr.head?.sha,
  rama: pr.head?.ref,
} }];

// El diff entero puede ser enorme y no cabe en una peticion barata. Se recorta, y se
// AVISA al modelo de que esta recortado: si no, se pone a sacar conclusiones sobre
// codigo que no ha visto, que es la forma mas facil de que una revision automatica
// diga tonterias con seguridad.
const MAX = 45000;
const prev = $('Elegir un PR').first().json;
const j = $input.first().json;
const diff = typeof j.data === 'string' ? j.data : (typeof j.body === 'string' ? j.body : '');
const recortado = diff.length > MAX;
const trozo = diff.slice(0, MAX);
const nl = String.fromCharCode(10);

const prompt = [
  'Eres la PRIMERA PASADA de revision de un pull request en un proyecto personal en espanol.',
  'No eres la revision definitiva: detras hay una revision humana y otra con un modelo mayor.',
  'Tu trabajo es cazar lo BARATO y lo OBVIO, no hacer arquitectura.',
  '',
  'Busca, por este orden:',
  '1. Que el cambio haga lo que dice el titulo. Si no encaja, dilo.',
  '2. Erratas y faltas de ortografia en textos de cara al usuario y en comentarios (el proyecto es en espanol, con tildes).',
  '3. Incoherencias evidentes: una variable que se declara y no se usa, un comentario que contradice al codigo, un copy-paste sin adaptar, un console.log o un print olvidado.',
  '4. Documentacion que se queda desfasada por este cambio.',
  '',
  'NO hagas esto:',
  '- No propongas refactorizaciones ni cambios de estilo.',
  '- No comentes lo que esta bien.',
  '- No inventes. Si no estas seguro, callate: un hallazgo falso cuesta mas que uno que se escapa.',
  '- No opines sobre codigo que no aparece en el diff.',
  '',
  'Responde SOLO con este JSON:',
  '{"hallazgos": [{"donde": "<fichero o zona>", "que": "<una frase>"}], "resumen": "<una frase, o cadena vacia si no hay nada>"}',
  'Si no hay nada que senalar, devuelve {"hallazgos": [], "resumen": ""}.',
  '',
  'Titulo del PR: ' + prev.titulo,
  'Descripcion: ' + (prev.cuerpo || '(sin descripcion)'),
  '',
  recortado ? 'AVISO: el diff esta RECORTADO, solo ves el principio.' : '',
  'Diff:',
  trozo,
].join(nl);

return [{ json: { ...prev, prompt, recortado } }];

// Saca los hallazgos y decide si merece la pena abrir la boca.
const cand = $input.first().json?.candidates?.[0];
let crudo = (cand?.content?.parts?.[0]?.text || '').trim();
crudo = crudo.replace(/^```(?:json)?/, '').replace(/```$/, '').trim();

const meta = $('Preparar la revision').first().json;
const estado = $getWorkflowStaticData('global');
const marcar = () => {
  estado.revisados = [...(estado.revisados || []), meta.numero + '@' + meta.sha].slice(-100);
};

let d;
try { d = JSON.parse(crudo); } catch (e) { d = null; }

// Si el modelo no contesta (el plan gratuito se satura a ratos), NO se marca como
// revisado: que vuelva a intentarlo en la vuelta siguiente. Al reves que en las
// averias, aqui no hay prisa y no se pierde nada esperando.
if (!d) return [];

marcar();

const hallazgos = Array.isArray(d.hallazgos) ? d.hallazgos : [];
// Silencio cuando no hay nada. Un bot que comenta «todo bien» en cada PR es un bot que
// se acaba silenciando, y con el se va el aviso que si importaba.
if (!hallazgos.length) return [];

const nl = String.fromCharCode(10);
const lineas = hallazgos.slice(0, 8).map(h => '- **' + (h.donde || '?') + '**: ' + h.que);

const cuerpo = [
  '### Primera pasada automatica',
  '',
  d.resumen || '',
  '',
  ...lineas,
  '',
  meta.recortado ? '_El diff era largo: solo se ha mirado el principio._' : '',
  '',
  '_Revision barata hecha con Gemini desde n8n: solo erratas y cosas obvias. No sustituye a la revision de verdad, y puede equivocarse._',
].join(nl);

return [{ json: { numero: meta.numero, cuerpo } }];
